#{couponId}
ORDER BY coupon_id FOR UPDATE

mapper.update:
UPDATE paid_coupon_inventory
SET remaining = remaining - CASE coupon_id

    WHEN #{item.couponId} THEN #{item.quantity}

ELSE 0 END
WHERE coupon_id IN

    #{item.couponId}

AND remaining >= CASE coupon_id

    WHEN #{item.couponId} THEN #{item.quantity}

ELSE 0 END
ORDER BY coupon_id

UPDATE paid_coupon_inventory
SET next_unit_id = #{nextUnitId}
WHERE coupon_id = #{couponId}
